import{_ as t,o,c as r,ag as a}from"./chunks/framework.B_zcDAFh.js";const p=JSON.parse('{"title":"Boing Effector","description":"","frontmatter":{},"headers":[],"relativePath":"guide/boing-effector.md","filePath":"guide/boing-effector.md"}'),i={name:"guide/boing-effector.md"};function f(n,e,c,s,l,d){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="boing-effector" tabindex="-1">Boing Effector <a class="header-anchor" href="#boing-effector" aria-label="Permalink to &quot;Boing Effector&quot;">​</a></h1><p>Add the <strong>Boing Effector</strong> component to a GameObject that should <em>push</em> other objects. Effectors don&#39;t move or deform themselves — they apply influence to nearby <a href="./boing-reactor.html">Boing Reactors</a>, <a href="./boing-reactor-field.html">Boing Reactor Fields</a>, and <a href="./boing-bones.html">Boing Bones</a>.</p><p>Typical effector setups:</p><ul><li>A player or projectile that nudges decorative objects aside as it passes.</li><li>A wind source that displaces grass, foliage, or hair.</li><li>An explosion radius that radiates outward through a reactor field.</li></ul><p>The shape of the influence (falloff, direction, type) is configured per-effector. See the <a href="/boing-kit/api/boing-effector.html">API reference</a> for the parameter list, and the <a href="/boing-kit/gallery/effector-reactor.html">Effector &amp; Reactor gallery</a> for example scenes.</p>',5)])])}const g=t(i,[["render",f]]);export{p as __pageData,g as default};
